import React from "react";
const Header = () => {
  return (
    <header className="flex justify-start">
      <img src="/images/icon.png" alt="Icon" />
      <li>
        <a href="home" className="hover">
          Home
        </a>
      </li>
    </header>
  );
};

export default Header;
